"use client";

import { TrendingDown, TrendingUp } from "lucide-react";

/* Dev tools top errors: the most frequent production errors in the last 24 hours with counts, share of the total and change versus the day before. A card, 1/2 width of a 12-column grid (6 columns), responsive to its container. */

export interface ErrorGroup {
  id: string;
  message: string;
  service: string;
  count: number;
  /** Percent change versus the previous 24 hours. */
  change: number;
}

export interface DevToolsTopErrorsProps {
  errors?: ErrorGroup[];
  onSelect?: (error: ErrorGroup) => void;
  className?: string;
}

export const DEMO_ERRORS: ErrorGroup[] = [
  { id: "e1", message: "TimeoutError: upstream request exceeded 8000ms", service: "api-gateway", count: 1842, change: 24 },
  { id: "e2", message: "TypeError: Cannot read properties of undefined (reading 'plan')", service: "web-app", count: 967, change: -11 },
  { id: "e3", message: "PrismaClientKnownRequestError: connection pool exhausted", service: "billing-worker", count: 410, change: 63 },
  { id: "e4", message: "RateLimitError: 429 from email provider", service: "notifier", count: 233, change: -4 },
  { id: "e5", message: "ValidationError: invalid cursor", service: "search-indexer", count: 88, change: 0 },
];

export function shareOf(count: number, total: number): number {
  return total === 0 ? 0 : Math.round((count / total) * 100);
}

const ring = "outline-none focus-visible:ring-2 focus-visible:ring-[var(--select)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg)]";

export function DevToolsTopErrors({ errors = DEMO_ERRORS, onSelect, className = "" }: DevToolsTopErrorsProps) {
  const ranked = [...errors].sort((a, b) => b.count - a.count);
  const total = ranked.reduce((s, e) => s + e.count, 0);
  const top = ranked[0]?.count ?? 1;
  return (
    <section aria-label="Top errors" className={`@container rounded-[20px] bg-surface p-4 shadow-[var(--shadow-card)] @[480px]:p-5 ${className}`}>
      <header className="mb-3 flex items-baseline justify-between gap-2">
        <h2 className="text-[15px] font-semibold text-fg">Top errors</h2>
        <span className="text-[12px] text-fg-muted">{total.toLocaleString("en-US")} events, 24h</span>
      </header>
      <ul className="grid gap-1">
        {ranked.map((e) => {
          const up = e.change > 0;
          const Arrow = up ? TrendingUp : TrendingDown;
          return (
            <li key={e.id}>
              <button type="button" onClick={() => onSelect?.(e)} className={`grid w-full gap-1.5 rounded-[12px] px-2 py-2 text-left hover:bg-[color-mix(in_srgb,var(--fg)_4%,var(--surface))] ${ring}`}>
                <span className="flex items-start gap-3">
                  <span className="min-w-0 flex-1">
                    <span className="block truncate font-mono text-[13px] text-fg">{e.message}</span>
                    <span className="block text-[12px] text-fg-muted">{e.service} · {shareOf(e.count, total)}% of errors</span>
                  </span>
                  <span className="text-right">
                    <span className="block text-[14px] font-semibold tabular-nums text-fg">{e.count.toLocaleString("en-US")}</span>
                    {e.change !== 0 && (
                      <span className={`inline-flex items-center gap-0.5 text-[12px] ${up ? "text-danger-text" : "text-success-text"}`}>
                        <Arrow size={12} aria-hidden />
                        {Math.abs(e.change)}%
                        <span className="sr-only">{up ? "more" : "fewer"} than the previous day</span>
                      </span>
                    )}
                  </span>
                </span>
                <span aria-hidden className="h-1 overflow-hidden rounded-full bg-track">
                  <span className="block h-full rounded-full" style={{ width: `${(e.count / top) * 100}%`, background: "var(--danger)", opacity: 0.75 }} />
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </section>
  );
}
